// Monta o markdown do snapshot diário
const all = $input.all();
const metrics = all.filter(i => i.json.day !== undefined);
const matches = all.filter(i => i.json.score !== undefined);
const apps = all.filter(i => i.json.status !== undefined);

const today = new Date().toISOString().slice(0, 10);
const totalSeen = metrics.reduce((s, m) => s + Number(m.json.jobs_seen ?? 0), 0);
const totalMatched = metrics.reduce((s, m) => s + Number(m.json.jobs_matched ?? 0), 0);
const totalSent = metrics.reduce((s, m) => s + Number(m.json.applications_sent ?? 0), 0);

let md = `# Snapshot ${today}\n\n`;
md += `## Resumo\n\n`;
md += `| Métrica | Valor |\n|---|---|\n`;
md += `| Vagas vistas | ${totalSeen} |\n`;
md += `| Vagas com match (≥70) | ${totalMatched} |\n`;
md += `| Aplicações enviadas | ${totalSent} |\n\n`;

md += `## Por fonte\n\n| Fonte | Vistas | Match | Enviadas |\n|---|---|---|---|\n`;
for (const m of metrics) {
  md += `| ${m.json.source} | ${m.json.jobs_seen} | ${m.json.jobs_matched} | ${m.json.applications_sent} |\n`;
}

if (matches.length) {
  md += `\n## Top matches do dia\n\n`;
  for (const m of matches) {
    md += `### ${m.json.title} — ${m.json.company ?? '?'} (${m.json.source}, score ${m.json.score})\n`;
    md += `${m.json.url}\n\n`;
    if (m.json.summary) md += `> ${m.json.summary}\n\n`;
  }
}

if (apps.length) {
  md += `\n## Aplicações do dia\n\n`;
  for (const a of apps) {
    md += `- **${a.json.title}** @ ${a.json.company ?? '?'} (${a.json.source}) — ${a.json.status}\n`;
  }
}

return [{ json: { date: today, markdown: md, path: `snapshots/${today}.md` } }];
